resetAction.code:
if (context.panel.response) {
  context.grafana.notifySuccess(['Update', 'Values updated successfully.']);
  context.grafana.refresh();
} else {
  context.grafana.notifyError(['Update', 'An error occurred updating values.']);
}

update.code:
const currentText = context.panel.elements.find(e => e.id === 'query_text').value;

fetch('/api/ds/query', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    queries: [{
      refId: 'A',
      datasource: { uid: 'bftgkx4uqs64ga', type: 'yesoreyeram-infinity-datasource' },
      type: 'json',
      source: 'url',
      format: 'as-is',
      url: 'https://dbc-270e414b-2aca.cloud.databricks.com/serving-endpoints/databricks-bge-large-en/invocations',
      url_options: {
        method: 'POST',
        body_type: 'raw',
        body_content_type: 'application/json',
        data: JSON.stringify({ input: [currentText] })
      },
      maxDataPoints: 100,
      intervalMs: 1000
    }],
    from: 'now-5m',
    to: 'now'
  })
})
  .then(function(res) { return res.json(); })
  .then(function(raw) {
    function deepFindNamed(obj, depth) {
      if (obj === null || obj === undefined || depth > 10) return null;
      if (Array.isArray(obj)) {
        for (let i = 0; i < obj.length; i++) {
          const found = deepFindNamed(obj[i], depth + 1);
          if (found) return found;
        }
        return null;
      }
      if (typeof obj === 'string') {
        try { return deepFindNamed(JSON.parse(obj), depth + 1); } catch (e) { return null; }
      }
      if (typeof obj === 'object') {
        if (Array.isArray(obj.embedding) && obj.embedding.length > 50) return obj.embedding;
        const keys = Object.keys(obj);
        for (let i = 0; i < keys.length; i++) {
          const found = deepFindNamed(obj[keys[i]], depth + 1);
          if (found) return found;
        }
      }
      return null;
    }

    function deepFindLargeArray(obj, depth) {
      if (obj === null || obj === undefined || depth > 10) return null;
      if (Array.isArray(obj)) {
        if (obj.length > 50 && typeof obj[0] === 'number') return obj;
        for (let i = 0; i < obj.length; i++) {
          const found = deepFindLargeArray(obj[i], depth + 1);
          if (found) return found;
        }
        return null;
      }
      if (typeof obj === 'string') {
        try { return deepFindLargeArray(JSON.parse(obj), depth + 1); } catch (e) { return null; }
      }
      if (typeof obj === 'object') {
        const keys = Object.keys(obj);
        for (let i = 0; i < keys.length; i++) {
          const found = deepFindLargeArray(obj[keys[i]], depth + 1);
          if (found) return found;
        }
      }
      return null;
    }

    const embedding = deepFindNamed(raw, 0) || deepFindLargeArray(raw, 0);
    if (!embedding) {
      let dump;
      try { dump = JSON.stringify(raw).slice(0, 800); } catch (e) { dump = String(raw).slice(0, 800); }
      context.grafana.notifyError(['Embedding', 'Could not parse embedding. Raw: ' + dump]);
      return;
    }
    const vectorStr = '[' + embedding.join(',') + ']';
    context.panel.patchFormValue({ computed_vector: vectorStr });
    context.grafana.locationService.partial({ 'var-embedding_vector': vectorStr }, true);
    context.grafana.refresh();
    context.grafana.notifySuccess(['Semantic Search', 'Vector computed (' + embedding.length + ' dims). Results updated below.']);
    runErrorAnalysis(vectorStr);
  })
  .catch(function(err) {
    context.grafana.notifyError(['Fetch Error', String(err)]);
  });

function extractFieldFromFrames(raw, fieldName) {
  try {
    const results = raw.results || {};
    const resultKeys = Object.keys(results);
    for (let r = 0; r < resultKeys.length; r++) {
      const frames = results[resultKeys[r]].frames || [];
      for (let f = 0; f < frames.length; f++) {
        const fields = (frames[f].schema && frames[f].schema.fields) || [];
        let idx = -1;
        for (let i = 0; i < fields.length; i++) {
          if (fields[i].name === fieldName) { idx = i; break; }
        }
        if (idx !== -1) {
          const values = frames[f].data && frames[f].data.values;
          if (values && values[idx] && values[idx].length > 0) {
            return values[idx][0];
          }
        }
      }
    }
  } catch (e) {}
  return null;
}

function extractAllValuesFromFrames(raw, fieldName) {
  try {
    const results = raw.results || {};
    const resultKeys = Object.keys(results);
    for (let r = 0; r < resultKeys.length; r++) {
      const frames = results[resultKeys[r]].frames || [];
      for (let f = 0; f < frames.length; f++) {
        const fields = (frames[f].schema && frames[f].schema.fields) || [];
        let idx = -1;
        for (let i = 0; i < fields.length; i++) {
          if (fields[i].name === fieldName) { idx = i; break; }
        }
        if (idx !== -1) {
          const values = frames[f].data && frames[f].data.values;
          if (values && values[idx]) return values[idx];
        }
      }
    }
  } catch (e) {}
  return [];
}

function runErrorAnalysis(vectorStr) {
  const sql = "SELECT log_raw, embedding_vector <=> '" + vectorStr + "'::vector AS distance FROM enriched_logs WHERE eventhub_timestamp >= NOW() - INTERVAL '6 hour' AND category != 'kernel' ORDER BY distance DESC LIMIT 10;";
  fetch('/api/ds/query', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      queries: [{
        refId: 'B',
        datasource: { uid: 'bfta8yj9xeghsb', type: 'grafana-postgresql-datasource' },
        rawSql: sql,
        format: 'table'
      }],
      from: 'now-5m',
      to: 'now'
    })
  })
    .then(function(res) { return res.json(); })
    .then(function(sqlRaw) {
      const logTexts = extractAllValuesFromFrames(sqlRaw, 'log_raw');
      if (!logTexts || logTexts.length === 0) {
        let dump;
        try { dump = JSON.stringify(sqlRaw).slice(0, 800); } catch (e) { dump = String(sqlRaw).slice(0, 800); }
        context.grafana.notifyError(['Analysis', 'Could not read log_raw from query result. Raw: ' + dump]);
        return null;
      }
      const combinedLogs = logTexts.map(function(t, i) { return (i + 1) + '. ' + t; }).join('\n');
      return fetch('/api/ds/query', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          queries: [{
            refId: 'C',
            datasource: { uid: 'bftgkx4uqs64ga', type: 'yesoreyeram-infinity-datasource' },
            type: 'json',
            source: 'url',
            format: 'as-is',
            url: 'https://dbc-270e414b-2aca.cloud.databricks.com/serving-endpoints/databricks-gpt-oss-20b/invocations',
            url_options: {
              method: 'POST',
              body_type: 'raw',
              body_content_type: 'application/json',
              data: JSON.stringify({
                messages: [{ role: 'user', content: 'Analyse the following top 10 most similar log entries:\n' + combinedLogs }],
                max_tokens: 500
              })
            },
            maxDataPoints: 100,
            intervalMs: 1000
          }],
          from: 'now-5m',
          to: 'now'
        })
      });
    })
    .then(function(res) { return res ? res.json() : null; })
    .then(function(llmRaw) {
      if (!llmRaw) return;
      let choices = extractFieldFromFrames(llmRaw, 'choices');
      if (typeof choices === 'string') {
        try { choices = JSON.parse(choices); } catch (e) { choices = null; }
      }
      if (!choices || !choices[0]) {
        let dump;
        try { dump = JSON.stringify(llmRaw).slice(0, 800); } catch (e) { dump = String(llmRaw).slice(0, 800); }
        context.grafana.notifyError(['Analysis', 'Could not parse LLM response. Raw: ' + dump]);
        return;
      }
      const content = choices[0].message ? choices[0].message.content : null;
      let answer = null;
      if (typeof content === 'string') {
        answer = content;
      } else if (Array.isArray(content)) {
        for (let i = 0; i < content.length; i++) {
          if (content[i] && typeof content[i].text === 'string') { answer = content[i].text; break; }
        }
        if (!answer && content[1] && content[1].text) answer = content[1].text;
      }
      if (!answer) {
        context.grafana.notifyError(['Analysis', 'LLM response had no text content.']);
        return;
      }
      context.panel.patchFormValue({ error_analysis: answer });
      context.grafana.notifySuccess(['Analysis', 'Error analysis complete.']);
    })
    .catch(function(err) {
      context.grafana.notifyError(['Analysis Error', String(err)]);
    });
}
